import java.util.Scanner;

// Buat kelas MemberLimitException, turunan Exception (checked), dengan constructor yang menerima pesan dan meneruskannya ke super.

class Member {
    private String name;
    private int loanCount = 0;
    private int maxLoan = 3;

    Member(String name) {
        this.name = name;
    }

    void borrow(String title) throws MemberLimitException {
        // Bila loanCount sudah mencapai maxLoan, lempar MemberLimitException dengan pesan name + " sudah mencapai batas " + maxLoan + " buku". Bila belum, tambah loanCount.
        loanCount++;
    }
}

public class Main {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        Member m = new Member(in.nextLine().trim());
        while (in.hasNextLine()) {
            String title = in.nextLine().trim();
            if (title.equals("selesai")) {
                break;
            }
            try {
                m.borrow(title);
                System.out.println("Berhasil: " + title);
            } catch (MemberLimitException e) {
                System.out.println("Gagal: " + e.getMessage());
            } finally {
                System.out.println("Transaksi selesai");
            }
        }
    }
}
